<script setup lang="ts">
/**
 * SPEC 63 CP-10.5: the stress line of a FORM page. The stress of the spelling itself where a source prints it (GG-14 lm/st: the stressed paradigm forms of the lemma, СУМ / r2u / en.wiktionary,
 * each with its source); else the lemma's stress (labelled as the lemma's); else the honest «наголос не встановлено (перевірено: …)». Nothing is generated by a rule.
 */
import { computed } from 'vue'
import type { StressVariant } from '../../core/types.ts'
import { renderStress } from '../../core/text.ts'
import { ST_SOURCES, formStress } from '../../core/stress-src.ts'
import { stOf, stLoaded } from '../lib/stressSrc.ts'
import StressForms from './StressForms.vue'
const props = defineProps<{ form: string; lemma: string; /** the lemma's stress variants of the detail shard (undefined while it loads) */ lemmaStress?: StressVariant[] }>()
const own = computed(() => formStress((stOf(props.lemma) ?? []).flatMap(e => e.forms), props.form))
const loading = computed(() => !stLoaded(props.lemma))
const name = (s: string) => ST_SOURCES[s]?.name ?? s
</script>

<template>
  <p class="hl-line sans small" data-testid="cp-stress">
    <span class="muted">наголос: </span>
    <template v-if="own.length"><span v-for="(g, i) in own" :key="i" data-testid="form-stress"><strong style="font-size:1.1rem">{{ renderStress(form, g.positions) }}</strong> <span class="muted">· {{ name(g.src) }} (написання)</span>{{ ' ' }}</span></template>
    <template v-else-if="lemmaStress?.length"><span class="muted">(леми) </span><StressForms :variants="lemmaStress" /></template>
    <span v-else-if="loading || !lemmaStress" class="muted">завантаження…</span>
    <span v-else class="unk" tabindex="0" data-testid="form-stress-none" title="немає доказів — значення не встановлено (P-3.1)">наголос не встановлено (перевірено: словниковий наголос ULIF, СУМ-11/20, словники r2u, en.wiktionary)</span>
  </p>
</template>
